// src/components/User/HeaderSearch.js
import React from 'react';

// Search Icon Component (from HomePage.js)
function SearchIcon() {
  return (
    <svg className="search-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" />
    </svg>
  );
}

export default function HeaderSearch({ searchTerm = '', onSearchChange, isCheckout = false }) {
    // If it's the checkout page, we hide the main header text and search bar
    // as the main content is the cart, but keep the space.
    if (isCheckout) {
        return (
            <div className="header-search-wrapper">
                {/* Header (Hidden on Checkout but required for layout positioning) */}
                <header className="home-header" style={{ opacity: 0, height: 0, marginBottom: 0 }}>
                    <h1>Hello, Guest</h1>
                    <p>What would you like to eat today?</p>
                </header>
                {/* Search Bar (Hidden on Checkout but required for layout positioning) */}
                <div className="search-bar" style={{ opacity: 0, height: 0, marginBottom: 0 }}>
                    <SearchIcon />
                    <input type="text" placeholder="Search for food..." disabled />
                </div>
            </div>
        );
    }
    
    // Normal Home Page view
    return (
        <div className="header-search-wrapper">
            <header className="home-header">
                <h1>Good evening</h1>
                <p>Place you order here</p>
            </header>
            <div className="search-bar">
                <SearchIcon />
                <input
                    type="text"
                    placeholder="Search for food..."
                    value={searchTerm}
                    onChange={onSearchChange}
                />
            </div>
        </div>
    );
}
